export const observationQuestions=['Do Andy and Tony maintain eye contact during the interview? Why do you think they do so?','At the end of the video, Tony invites Janet and Andy for a meal. How do Janet and Andy respond to the invitation? Can you propose alternative ways to extend and respond to invitations?'];
export const observationTranscript='Offline dialogue fixture: Tony talks about his restaurant and invites his visitors to a meal. They accept politely and thank him. This dialogue text does not describe gaze, expressions or physical movements.';
export const observationAnswers=['A fixture interpretation based on the supplied video frames.','They accept and thank him. An alternative is: Would you like to join us for lunch?'];
export function observationHTML({transcript=false,visual=true}={}){
  const questions=[...observationQuestions];if(!visual)questions[0]='What does Tony invite the visitors to do?';
  return `<!doctype html><html><head><meta charset="utf-8"></head><body><header><nav class="pc-break-crumb"><span class="pc-break-crumb-text">Offline listening book</span><span class="pc-break-crumb-text">Beyond the horizon</span><span class="pc-break-crumb-text">Conversation</span></nav><div class="pc-header-tab-activity">Conversation 2</div><div class="pc-task pc-header-task-activity">Exercise 2</div></header>
  <main class="layout-container"><div class="abs-direction">Watch Conversation 2 again and answer the following questions.</div><div class="layout-material-container"><video style="width:320px;height:180px" src="https://ucontent.unipus.cn/offline-recognition/visual-media.mp4"></video>${transcript?'<div class="transcript">'+observationTranscript+'</div>':''}</div>${questions.map(q=>'<fieldset><legend>'+q+'</legend><textarea></textarea></fieldset>').join('')}</main><footer><button id="submit">提交</button></footer>
  <script>window.playEvents=0;window.seekEvents=0;window.submitted=false;document.querySelector('video').addEventListener('play',()=>window.playEvents++);document.querySelector('video').addEventListener('seeking',()=>window.seekEvents++);document.querySelector('#submit').onclick=()=>{window.submitted=true;document.querySelector('main').innerHTML='<h2>答题小结</h2><p>共2道题，主观题2道</p><p>正确 (2/2)</p><p>错误 (0/2)</p><p>未作答0</p>';document.querySelector('footer').innerHTML='';};</script></body></html>`;
}
